/**
 * storage-cleanup Edge Function: deletes the files of deleted photos (drain.ts). Called by
 * pg_cron every 10 minutes while the queue is not empty (configure_storage_cleanup() in
 * supabase/migrations/20261029130000_photo_storage.sql).
 *
 * - Deployed without JWT verification; the caller proves itself with the shared secret in
 *   `x-cleanup-secret` (generated by `npm run photos -- --setup-cleanup`, kept in Vault and in
 *   the function's secrets). Anything else gets 401 before the queue is touched.
 * - Logs only counts: never file names or the secret.
 *
 * No Deno APIs here (index.ts reads the environment and creates the client), so vitest covers
 * all of it.
 */
import { drain, type DeletionQueue } from './drain.ts';

export type CleanupEnv = { STORAGE_CLEANUP_SECRET?: string };

type Log = (message: string) => void;

export const SECRET_HEADER = 'x-cleanup-secret';

const json = (status: number, body: unknown) =>
	new Response(JSON.stringify(body), {
		status,
		headers: { 'Content-Type': 'application/json' }
	});

/** Same time whatever the first differing character, so the secret cannot be guessed by timing. */
export function sameSecret(given: string, expected: string): boolean {
	const a = new TextEncoder().encode(given);
	const b = new TextEncoder().encode(expected);
	let diff = a.length ^ b.length;
	for (let i = 0; i < b.length; i++) diff |= (a[i] ?? 0) ^ b[i];
	return diff === 0;
}

export async function handleStorageCleanup(
	request: Request,
	env: CleanupEnv,
	queue: () => DeletionQueue,
	log: Log = console.log
): Promise<Response> {
	if (request.method !== 'POST') return json(405, { error: 'method_not_allowed' });
	const expected = env.STORAGE_CLEANUP_SECRET ?? '';
	const given = request.headers.get(SECRET_HEADER) ?? '';
	if (expected.length < 32 || !sameSecret(given, expected)) {
		return json(401, { error: 'unauthorized' });
	}
	try {
		const result = await drain(queue());
		log(`storage-cleanup: removed ${result.removed}, failed ${result.failed}`);
		return json(200, result);
	} catch (error) {
		log(`storage-cleanup: ${error instanceof Error ? error.message : 'failed'}`);
		return json(500, { error: 'cleanup_failed' });
	}
}
